    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The bisimplicial Alexander–Whitney map", H("The bisimplicial Alexander–Whitney map"), Blocks(
        Paragraph(Text("Let C : Type u have Category.{v} C, with object and morphism universes independent. A bisimplicial object is a simplicial object in simplicial objects of C. Its diagonal in degree n is X[n,n], with both simplex operators acting together. The diagonal functor itself needs only the category structure. The chain-complex constructions in this module assume Abelian C.")),
        Paragraph(Text("FOne(X) is the natural-number total complex of the double alternating-face complex of X. Its degree n object is the finite coproduct over p+q=n, and its differential on bidegree (p,q) is the first differential plus (-1)^p times the second. FTwo(X) is the alternating-face chain complex of the diagonal. Finite antidiagonals require only coproducts already available in an abelian category.")),
        Paragraph(Text("The front coface selects the first p+1 vertices of [p+q], and the back coface selects the last q+1. Applying these in the two simplicial variables gives awComponent : X[p+q,p+q] → X[p,q]. Summing its inclusions into the total complex gives alexanderWhitney : FTwo(X) → FOne(X). The coface identities separate the two total boundary directions with the required sign.")),
